@CrossOrigin
@RestController
@RequestMapping("/CoverageQuery")
public class CoverageQueryRestController extends BaseSpringRestController {
	
	public CoverageQueryRestController( CoverageService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Coverage using a UUID
     * @param		UUID coverageId
     * @return		Coverage
     */    
    @GetMapping("/load")
    public Coverage load( @RequestParam(required=true) UUID coverageId ) {
    	Coverage entity = null;

    	try {  
    		entity = service.getCoverage( new CoverageFetchOneSummary( coverageId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Coverage using Id " + coverageId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Coverage business objects
     * @return		Set<Coverage>
     */
    @GetMapping("/")
    public List<Coverage> loadAll() {                
    	List<Coverage> coverageList = null;
        
    	try {
            // load the Coverage
            coverageList = service.getAllCoverage();
            
            if ( coverageList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Coverages" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Coverages ", exc );
        	return null;
        }

        return coverageList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Coverage coverage = null;
    protected CoverageService service = null;
    private static final Logger LOGGER = Logger.getLogger(CoverageQueryRestController.class.getName());
    
}
